with d as (select value r from jsonb_array_elements($q$[{"slug":"hot-and-sour-soup","title":"Hot and Sour Soup","cuisine":"chinese","meal_types":["lunch","dinner"],"diets":["no-dairy"],"difficulty":"easy","total_minutes":40,"recipe":{"id":"hot-and-sour-soup","title":"Hot and Sour Soup","summary":"A silky Chinese soup with pork, shiitake, tofu and egg ribbons, sharp with black vinegar and hot with white pepper.","cuisine":"chinese","diets":["no-dairy"],"mealTypes":["lunch","dinner"],"difficulty":"easy","prepMinutes":25,"cookMinutes":15,"servings":4,"onePot":true,"seasons":["autumn","winter"],"ingredientGroups":[{"title":"Pork","items":[{"item":"pork fillet","raw":"150g pork fillet, cut into thin matchsticks","quantity":150,"unit":"g","ingredientId":"pork-fillet","prep":"cut into thin matchsticks"},{"item":"soy sauce","raw":"1 tsp soy sauce","quantity":1,"unit":"tsp","ingredientId":"soy-sauce"},{"item":"cornflour","raw":"1 tsp cornflour","quantity":1,"unit":"tsp","ingredientId":"cornflour"}]},{"title":"Soup","items":[{"item":"dried shiitake mushrooms","raw":"6 dried shiitake mushrooms","quantity":6,"ingredientId":"dried-shiitake"},{"item":"boiling water","raw":"250ml boiling water","quantity":250,"unit":"ml","ingredientId":"water"},{"item":"chicken stock","raw":"1.25L chicken stock","quantity":1.25,"unit":"l","ingredientId":"chicken-stock"},{"item":"firm tofu","raw":"150g firm tofu, cut into thin strips","quantity":150,"unit":"g","ingredientId":"tofu","prep":"cut into thin strips"},{"item":"light soy sauce","raw":"3 tbsp light soy sauce","quantity":3,"unit":"tbsp","ingredientId":"soy-sauce"},{"item":"white sugar","raw":"1 tsp white sugar","quantity":1,"unit":"tsp","ingredientId":"sugar"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"},{"item":"cornflour","raw":"3 tbsp cornflour","quantity":3,"unit":"tbsp","ingredientId":"cornflour"},{"item":"cold water","raw":"4 tbsp cold water","quantity":4,"unit":"tbsp","ingredientId":"water"},{"item":"eggs","raw":"2 eggs, beaten","quantity":2,"ingredientId":"egg","prep":"beaten"},{"item":"Chinkiang black vinegar","raw":"4 tbsp Chinkiang black vinegar","quantity":4,"unit":"tbsp","ingredientId":"black-vinegar"},{"item":"white vinegar","raw":"1 tbsp white vinegar","quantity":1,"unit":"tbsp","ingredientId":"white-vinegar"},{"item":"ground white pepper","raw":"1 tsp ground white pepper","quantity":1,"unit":"tsp","ingredientId":"white-pepper"},{"item":"sesame oil","raw":"1 tsp sesame oil","quantity":1,"unit":"tsp","ingredientId":"sesame-oil"},{"item":"chilli oil","raw":"1 tsp chilli oil","quantity":1,"unit":"tsp","ingredientId":"chilli-oil"},{"item":"spring onions","raw":"2 spring onions, sliced","quantity":2,"ingredientId":"spring-onion","prep":"sliced"}]}],"steps":[{"text":"Soak the shiitake in the boiling water for 20 minutes. Squeeze them out, keeping the liquid, cut off the stems and slice the caps thinly. Meanwhile, mix the pork with the soy sauce and cornflour."},{"text":"Bring the stock, mushroom liquid (leave any grit behind) and sliced shiitake to the boil in a large saucepan. Simmer for 5 minutes."},{"text":"Add the pork, stirring to separate the pieces, and simmer for 2 to 3 minutes until cooked through. Add the tofu, soy sauce, sugar and salt."},{"text":"Mix the cornflour with the cold water, stir it into the soup and simmer for 1 minute until glossy and slightly thickened."},{"text":"Turn the heat to low. Pour in the eggs in a thin stream while stirring the soup slowly in one direction, so they set in ribbons. Take off the heat."},{"text":"Stir in both vinegars, the white pepper, sesame oil and chilli oil. Taste: it should be sour and peppery. Serve topped with spring onion."}],"notes":["Add the vinegar and pepper off the heat; boiling dulls them.","Sliced bamboo shoots and wood ear mushrooms from an Asian grocer are traditional additions. Add them with the tofu.","Food safety: Cook fresh pork to at least 70°C in the thickest part."],"source":"user","provenance":"ai-draft"}},{"slug":"beef-and-broccoli","title":"Beef and Broccoli","cuisine":"chinese","meal_types":["dinner"],"diets":["no-dairy"],"difficulty":"easy","total_minutes":37,"recipe":{"id":"beef-and-broccoli","title":"Beef and Broccoli","summary":"Tender, velveted beef and crisp broccoli in a glossy oyster and garlic sauce, faster than takeaway.","cuisine":"chinese","diets":["no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":25,"cookMinutes":12,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Beef","items":[{"item":"beef rump","raw":"500g beef rump, trimmed and thinly sliced across the grain","quantity":500,"unit":"g","ingredientId":"beef-rump","prep":"trimmed and thinly sliced across the grain"},{"item":"soy sauce","raw":"1 tbsp soy sauce","quantity":1,"unit":"tbsp","ingredientId":"soy-sauce"},{"item":"Shaoxing wine","raw":"1 tbsp Shaoxing wine","quantity":1,"unit":"tbsp","ingredientId":"shaoxing-wine"},{"item":"cornflour","raw":"2 tsp cornflour","quantity":2,"unit":"tsp","ingredientId":"cornflour"},{"item":"neutral oil","raw":"1 tbsp neutral oil","quantity":1,"unit":"tbsp","ingredientId":"neutral-oil"}]},{"title":"Sauce","items":[{"item":"oyster sauce","raw":"3 tbsp oyster sauce","quantity":3,"unit":"tbsp","ingredientId":"oyster-sauce"},{"item":"soy sauce","raw":"1 tbsp soy sauce","quantity":1,"unit":"tbsp","ingredientId":"soy-sauce"},{"item":"dark soy sauce","raw":"1 tsp dark soy sauce","quantity":1,"unit":"tsp","ingredientId":"dark-soy-sauce"},{"item":"sugar","raw":"2 tsp sugar","quantity":2,"unit":"tsp","ingredientId":"sugar"},{"item":"cornflour","raw":"2 tsp cornflour","quantity":2,"unit":"tsp","ingredientId":"cornflour"},{"item":"water","raw":"125ml water","quantity":125,"unit":"ml","ingredientId":"water"}]},{"title":"Stir-fry","items":[{"item":"neutral oil","raw":"3 tbsp neutral oil","quantity":3,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"large head broccoli","raw":"1 large head broccoli, cut into small florets","quantity":1,"ingredientId":"broccoli","prep":"cut into small florets"},{"item":"garlic","raw":"3 garlic cloves, finely chopped","quantity":3,"unit":"clove","ingredientId":"garlic","prep":"finely chopped"},{"item":"ginger","raw":"1 tbsp ginger, finely chopped","quantity":1,"unit":"tbsp","ingredientId":"ginger","prep":"finely chopped"},{"item":"spring onions","raw":"2 spring onions, cut into 3cm lengths","quantity":2,"ingredientId":"spring-onion","prep":"cut into 3cm lengths"}]},{"title":"To serve","items":[{"item":"Steamed jasmine rice","raw":"Steamed jasmine rice","ingredientId":"jasmine-rice"}]}],"steps":[{"text":"Toss the beef with the soy sauce, Shaoxing wine, cornflour and 1 tbsp oil. Leave for 15 minutes while you prepare everything else."},{"text":"Whisk the sauce ingredients together until the cornflour dissolves."},{"text":"Heat 1 tbsp oil in a wok over high heat. Add the broccoli and 3 tbsp water and stir-fry for 3 minutes, until bright green and just tender. Tip onto a plate."},{"text":"Add 1 tbsp oil to the hot wok and spread half the beef out in one layer. Sear for 1 minute without moving, then toss for 30 seconds more and lift out. Repeat with the rest of the oil and beef."},{"text":"Lower the heat to medium, add the garlic, ginger and spring onion and stir for 30 seconds. Whisk the sauce again, pour it in and bubble for 1 minute until thick and glossy."},{"text":"Return the beef and broccoli and toss for 1 minute to coat and heat through. Serve straight away with rice."}],"notes":["Slicing across the grain and cooking in two batches is what keeps the beef tender. A crowded wok stews the meat.","Put the beef in the freezer for 20 minutes first and it slices thinly far more easily.","Food safety: Steaks and roasting cuts of beef or lamb can be served pink: about 60°C in the centre is medium-rare, 70°C is well done."],"source":"user","provenance":"ai-draft"}},{"slug":"smashed-cucumber-salad","title":"Smashed Cucumber Salad","cuisine":"chinese","meal_types":["snack","lunch"],"diets":["vegetarian","vegan","no-dairy"],"difficulty":"easy","total_minutes":25,"recipe":{"id":"smashed-cucumber-salad","title":"Smashed Cucumber Salad","summary":"Cold, crunchy smashed cucumbers in a garlicky black vinegar and chilli oil dressing.","cuisine":"chinese","diets":["vegetarian","vegan","no-dairy"],"mealTypes":["snack","lunch"],"difficulty":"easy","prepMinutes":25,"cookMinutes":0,"servings":4,"onePot":false,"seasons":["spring","summer"],"ingredientGroups":[{"items":[{"item":"Lebanese cucumbers","raw":"4 Lebanese cucumbers","quantity":4,"ingredientId":"cucumber"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"sugar","raw":"1 tsp sugar","quantity":1,"unit":"tsp","ingredientId":"sugar"},{"item":"garlic","raw":"3 garlic cloves, finely grated","quantity":3,"unit":"clove","ingredientId":"garlic","prep":"finely grated"},{"item":"Chinkiang black vinegar","raw":"2 tbsp Chinkiang black vinegar","quantity":2,"unit":"tbsp","ingredientId":"black-vinegar"},{"item":"soy sauce","raw":"1 tbsp soy sauce","quantity":1,"unit":"tbsp","ingredientId":"soy-sauce"},{"item":"chilli oil","raw":"1 tbsp chilli oil","quantity":1,"unit":"tbsp","ingredientId":"chilli-oil"},{"item":"sesame oil","raw":"2 tsp sesame oil","quantity":2,"unit":"tsp","ingredientId":"sesame-oil"},{"item":"sesame seeds","raw":"1 tsp sesame seeds, toasted","quantity":1,"unit":"tsp","ingredientId":"sesame-seeds","prep":"toasted"},{"item":"coriander leaves","raw":"Small handful of coriander leaves","quantity":1,"unit":"handful","ingredientId":"coriander","note":"small handful"}]}],"steps":[{"text":"Lay a cucumber on a board and whack it along its length with the flat of a large knife or a rolling pin until it cracks open. Cut it into 3cm chunks on an angle. Repeat with the rest."},{"text":"Toss the cucumber with the salt and sugar in a colander and leave over a bowl for 15 minutes to draw out the water. Shake off the liquid and tip into a serving bowl."},{"text":"Mix the garlic, vinegar, soy sauce, chilli oil and sesame oil."},{"text":"Pour the dressing over the cucumber and toss. Scatter with sesame seeds and coriander and serve cold, within an hour."}],"notes":["Smashing rather than slicing gives rough edges that hold far more dressing.","Black vinegar and soy sauce both contain wheat, so this isn't gluten-free. Use tamari and rice vinegar if you need it to be."],"source":"user","provenance":"ai-draft"}},{"slug":"onigiri","title":"Onigiri","cuisine":"japanese","meal_types":["lunch","snack"],"diets":["pescatarian","no-dairy"],"difficulty":"easy","total_minutes":50,"recipe":{"id":"onigiri","title":"Onigiri","summary":"Japanese rice balls with a tuna-mayo centre, wrapped in crisp nori. Lunchbox gold.","cuisine":"japanese","diets":["pescatarian","no-dairy"],"mealTypes":["lunch","snack"],"difficulty":"easy","prepMinutes":30,"cookMinutes":20,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Rice","items":[{"item":"sushi rice","raw":"400g sushi rice","quantity":400,"unit":"g","ingredientId":"sushi-rice"},{"item":"water","raw":"480ml water","quantity":480,"unit":"ml","ingredientId":"water"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"}]},{"title":"Tuna-mayo filling","items":[{"item":"tuna in olive oil","raw":"185g tin tuna in olive oil, well drained","quantity":185,"unit":"g","ingredientId":"tinned-tuna","prep":"well drained","note":"tin"},{"item":"Kewpie mayonnaise","raw":"2 tbsp Kewpie mayonnaise","quantity":2,"unit":"tbsp","ingredientId":"kewpie-mayonnaise"},{"item":"soy sauce","raw":"1 tsp soy sauce","quantity":1,"unit":"tsp","ingredientId":"soy-sauce"},{"item":"spring onion","raw":"1 spring onion, finely sliced","quantity":1,"ingredientId":"spring-onion","prep":"finely sliced"}]},{"title":"To finish","items":[{"item":"nori","raw":"4 nori sheets, cut in half","quantity":4,"unit":"sheet","ingredientId":"nori","prep":"cut in half"},{"item":"sesame seeds","raw":"1 tbsp sesame seeds, toasted","quantity":1,"unit":"tbsp","ingredientId":"sesame-seeds","prep":"toasted"}]}],"steps":[{"text":"Rinse the rice in a sieve under cold water, rubbing it with your hand, until the water runs almost clear. Put it in a saucepan with the water and soak for 10 minutes."},{"text":"Bring to the boil, cover tightly and cook on the lowest heat for 12 minutes. Turn off the heat and leave covered for 10 minutes. Spread onto a tray to cool until warm enough to handle, about 10 minutes."},{"text":"Mix the tuna, mayonnaise, soy sauce and spring onion."},{"text":"Wet your hands and rub them with a little of the salt. Take about 100g of rice, flatten it in your palm and put a heaped teaspoon of filling in the middle. Close the rice over the filling and press firmly into a triangle, turning it in your cupped hands. Make 8."},{"text":"Sprinkle with sesame seeds and wrap a half sheet of nori around the base of each just before eating, so it stays crisp."}],"notes":["Shape the rice while it's still warm, or it won't stick together. Once made, eat within a few hours or refrigerate and eat the same day. Cooked rice shouldn't sit at room temperature for long.","Packed for lunch, keep the onigiri in an insulated bag with an ice brick, and the nori separate so it doesn't go soggy."],"source":"user","provenance":"ai-draft"}},{"slug":"chicken-karaage","title":"Chicken Karaage","cuisine":"japanese","meal_types":["dinner","snack"],"diets":["no-dairy"],"difficulty":"medium","total_minutes":70,"recipe":{"id":"chicken-karaage","title":"Chicken Karaage","summary":"Ginger and soy marinated chicken thigh, double-fried in a potato starch coat until shatteringly crisp.","cuisine":"japanese","diets":["no-dairy"],"mealTypes":["dinner","snack"],"difficulty":"medium","prepMinutes":45,"cookMinutes":25,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Chicken","items":[{"item":"chicken thigh fillets","raw":"800g chicken thigh fillets, cut into 4cm pieces","quantity":800,"unit":"g","ingredientId":"chicken-thigh","prep":"cut into 4cm pieces"},{"item":"soy sauce","raw":"3 tbsp soy sauce","quantity":3,"unit":"tbsp","ingredientId":"soy-sauce"},{"item":"sake","raw":"2 tbsp sake","quantity":2,"unit":"tbsp","ingredientId":"sake"},{"item":"ginger","raw":"1 tbsp ginger, finely grated","quantity":1,"unit":"tbsp","ingredientId":"ginger","prep":"finely grated"},{"item":"garlic","raw":"2 garlic cloves, finely grated","quantity":2,"unit":"clove","ingredientId":"garlic","prep":"finely grated"},{"item":"sugar","raw":"1 tsp sugar","quantity":1,"unit":"tsp","ingredientId":"sugar"},{"item":"potato starch","raw":"100g potato starch","quantity":100,"unit":"g","ingredientId":"potato-starch"},{"item":"neutral oil","raw":"1.5L neutral oil, for deep-frying","quantity":1.5,"unit":"l","ingredientId":"neutral-oil","prep":"for deep-frying"}]},{"title":"To serve","items":[{"item":"Kewpie mayonnaise","raw":"4 tbsp Kewpie mayonnaise","quantity":4,"unit":"tbsp","ingredientId":"kewpie-mayonnaise"},{"item":"lemon","raw":"1 lemon, cut into wedges","quantity":1,"ingredientId":"lemon","prep":"cut into wedges"},{"item":"iceberg lettuce","raw":"1/4 iceberg lettuce, finely shredded","quantity":0.25,"ingredientId":"iceberg-lettuce","prep":"finely shredded"}]}],"steps":[{"text":"Mix the chicken with the soy sauce, sake, ginger, garlic and sugar. Cover and refrigerate for 30 minutes, or up to 4 hours."},{"text":"Pour the oil into a large, heavy saucepan no more than one-third full and heat to 170°C on a cooking thermometer. Keep a lid nearby and never leave the pan."},{"text":"Drain the chicken and toss a few pieces at a time in the potato starch, shaking off the excess."},{"text":"Fry in batches of 6 to 8 pieces for 3 minutes, until pale golden. Lift onto a wire rack. Let the oil come back to 170°C between batches."},{"text":"When it's all fried once, heat the oil to 190°C and fry the pieces again in batches for 1 to 2 minutes, until deep golden and very crisp, and cooked through (75°C in the centre of the largest piece). Drain on the rack."},{"text":"Serve hot with lettuce, Kewpie mayonnaise and lemon wedges."}],"notes":["The rest between the two fries lets heat reach the centre, and the second hot fry dries the crust so it stays crisp.","Let the oil cool completely in the pan before straining it for reuse or disposing of it.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"source":"user","provenance":"ai-draft"}},{"slug":"japchae","title":"Japchae","cuisine":"korean","meal_types":["dinner","lunch"],"diets":["no-dairy"],"difficulty":"medium","total_minutes":50,"recipe":{"id":"japchae","title":"Japchae","summary":"Chewy sweet potato noodles tossed with beef, vegetables and sesame in a sweet soy dressing.","cuisine":"korean","diets":["no-dairy"],"mealTypes":["dinner","lunch"],"difficulty":"medium","prepMinutes":30,"cookMinutes":20,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Sauce","items":[{"item":"soy sauce","raw":"5 tbsp soy sauce","quantity":5,"unit":"tbsp","ingredientId":"soy-sauce"},{"item":"sugar","raw":"2 tbsp sugar","quantity":2,"unit":"tbsp","ingredientId":"sugar"},{"item":"sesame oil","raw":"2 tbsp sesame oil","quantity":2,"unit":"tbsp","ingredientId":"sesame-oil"},{"item":"garlic","raw":"2 garlic cloves, finely grated","quantity":2,"unit":"clove","ingredientId":"garlic","prep":"finely grated"}]},{"title":"Noodles","items":[{"item":"sweet potato noodles","raw":"250g sweet potato noodles (dangmyeon)","quantity":250,"unit":"g","ingredientId":"glass-noodles","note":"dangmyeon"},{"item":"beef rump","raw":"250g beef rump, cut into thin strips","quantity":250,"unit":"g","ingredientId":"beef-rump","prep":"cut into thin strips"},{"item":"neutral oil","raw":"2 tbsp neutral oil","quantity":2,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"brown onion","raw":"1 brown onion, thinly sliced","quantity":1,"ingredientId":"brown-onion","prep":"thinly sliced"},{"item":"carrot","raw":"1 carrot, cut into matchsticks","quantity":1,"ingredientId":"carrot","prep":"cut into matchsticks"},{"item":"red capsicum","raw":"1 red capsicum, thinly sliced","quantity":1,"ingredientId":"capsicum","prep":"thinly sliced"},{"item":"shiitake mushrooms","raw":"6 shiitake mushrooms, thinly sliced","quantity":6,"ingredientId":"shiitake-mushroom","prep":"thinly sliced"},{"item":"baby spinach","raw":"150g baby spinach","quantity":150,"unit":"g","ingredientId":"baby-spinach"},{"item":"spring onions","raw":"3 spring onions, cut into 4cm lengths","quantity":3,"ingredientId":"spring-onion","prep":"cut into 4cm lengths"},{"item":"sesame seeds","raw":"1 tbsp sesame seeds, toasted","quantity":1,"unit":"tbsp","ingredientId":"sesame-seeds","prep":"toasted"}]}],"steps":[{"text":"Mix the sauce ingredients. Toss the beef with 1 tbsp of the sauce."},{"text":"Cook the noodles in a large saucepan of boiling water for 6 minutes, until soft and chewy. Drain, rinse under cold water and drain well. Snip into shorter lengths with kitchen scissors and toss with 2 tbsp of the sauce."},{"text":"Heat 1 tbsp oil in a wok or large frying pan over medium-high heat. Stir-fry the onion and carrot for 2 minutes, then the capsicum for 1 minute. Tip into a large bowl."},{"text":"Stir-fry the mushrooms for 2 minutes and add to the bowl. Wilt the spinach for 30 seconds and add to the bowl."},{"text":"Add the rest of the oil and stir-fry the beef for 2 minutes until browned and cooked. Add to the bowl."},{"text":"Put the noodles and spring onion in the wok with the rest of the sauce and toss over medium heat for 2 minutes until hot. Tip into the bowl and toss everything together with your hands or tongs. Scatter with sesame seeds and serve warm or at room temperature."}],"notes":["Cooking each vegetable separately keeps the colours bright and nothing goes soggy.","For a vegetarian version, leave out the beef and add 200g sliced firm tofu, pan-fried until golden.","Food safety: Steaks and roasting cuts of beef or lamb can be served pink: about 60°C in the centre is medium-rare, 70°C is well done."],"source":"user","provenance":"ai-draft"}},{"slug":"pajeon","title":"Pajeon","cuisine":"korean","meal_types":["snack","lunch"],"diets":["vegetarian","no-dairy"],"difficulty":"easy","total_minutes":30,"recipe":{"id":"pajeon","title":"Pajeon","summary":"A crisp Korean spring onion pancake, served in wedges with a tangy soy dipping sauce.","cuisine":"korean","diets":["vegetarian","no-dairy"],"mealTypes":["snack","lunch"],"difficulty":"easy","prepMinutes":15,"cookMinutes":15,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Pancakes","items":[{"item":"plain flour","raw":"150g plain flour","quantity":150,"unit":"g","ingredientId":"plain-flour"},{"item":"potato starch","raw":"2 tbsp potato starch","quantity":2,"unit":"tbsp","ingredientId":"potato-starch"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"},{"item":"egg","raw":"1 egg","quantity":1,"ingredientId":"egg"},{"item":"cold water","raw":"250ml cold water","quantity":250,"unit":"ml","ingredientId":"water"},{"item":"spring onions","raw":"2 bunches spring onions, cut into 10cm lengths","quantity":2,"unit":"bunch","ingredientId":"spring-onion","prep":"cut into 10cm lengths"},{"item":"long red chilli","raw":"1 long red chilli, thinly sliced","quantity":1,"ingredientId":"red-chilli","prep":"thinly sliced"},{"item":"neutral oil","raw":"4 tbsp neutral oil","quantity":4,"unit":"tbsp","ingredientId":"neutral-oil"}]},{"title":"Dipping sauce","items":[{"item":"soy sauce","raw":"3 tbsp soy sauce","quantity":3,"unit":"tbsp","ingredientId":"soy-sauce"},{"item":"rice vinegar","raw":"1 tbsp rice vinegar","quantity":1,"unit":"tbsp","ingredientId":"rice-vinegar"},{"item":"sugar","raw":"1 tsp sugar","quantity":1,"unit":"tsp","ingredientId":"sugar"},{"item":"gochugaru","raw":"1/2 tsp gochugaru","quantity":0.5,"unit":"tsp","ingredientId":"gochugaru"},{"item":"sesame seeds","raw":"1/2 tsp sesame seeds","quantity":0.5,"unit":"tsp","ingredientId":"sesame-seeds"}]}],"steps":[{"text":"Mix the dipping sauce ingredients and set aside."},{"text":"Whisk the flour, potato starch, salt, egg and cold water to a smooth, thin batter."},{"text":"Heat 2 tbsp oil in a large frying pan over medium-high heat. Lay half the spring onions in the pan in a single layer, all facing the same way. Pour over half the batter to just coat them, and scatter with half the chilli."},{"text":"Cook for 4 minutes, pressing down with a spatula, until golden and crisp underneath. Flip and cook for 3 to 4 minutes more, adding a little more oil around the edge, until crisp."},{"text":"Slide onto a board and repeat with the rest. Cut into wedges and serve hot with the dipping sauce."}],"notes":["Cold water and a hot, well-oiled pan are what make it crisp rather than doughy.","For haemul pajeon, scatter 150g chopped raw prawns or squid over the spring onions before adding the batter, and cook until the seafood is opaque.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"source":"user","provenance":"ai-draft"}},{"slug":"gimbap","title":"Gimbap","cuisine":"korean","meal_types":["lunch","snack"],"diets":["no-gluten","no-dairy"],"difficulty":"medium","total_minutes":75,"recipe":{"id":"gimbap","title":"Gimbap","summary":"Korean seaweed rice rolls with egg, ham, spinach, carrot and pickled radish, sliced into rounds.","cuisine":"korean","diets":["no-gluten","no-dairy"],"mealTypes":["lunch","snack"],"difficulty":"medium","prepMinutes":45,"cookMinutes":30,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Rice","items":[{"item":"sushi rice","raw":"400g sushi rice","quantity":400,"unit":"g","ingredientId":"sushi-rice"},{"item":"water","raw":"480ml water","quantity":480,"unit":"ml","ingredientId":"water"},{"item":"sesame oil","raw":"1 tbsp sesame oil","quantity":1,"unit":"tbsp","ingredientId":"sesame-oil"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"sesame seeds","raw":"1 tbsp sesame seeds, toasted","quantity":1,"unit":"tbsp","ingredientId":"sesame-seeds","prep":"toasted"}]},{"title":"Fillings","items":[{"item":"eggs","raw":"3 eggs, beaten with a pinch of salt","quantity":3,"ingredientId":"egg","prep":"beaten with a pinch of salt"},{"item":"neutral oil","raw":"1 tbsp neutral oil","quantity":1,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"English spinach","raw":"1 bunch English spinach, trimmed","quantity":1,"unit":"bunch","ingredientId":"spinach","prep":"trimmed"},{"item":"sesame oil","raw":"1 tsp sesame oil","quantity":1,"unit":"tsp","ingredientId":"sesame-oil"},{"item":"large carrot","raw":"1 large carrot, cut into matchsticks","quantity":1,"ingredientId":"carrot","prep":"cut into matchsticks"},{"item":"sliced ham","raw":"150g sliced ham, cut into strips","quantity":150,"unit":"g","ingredientId":"ham","prep":"cut into strips"},{"item":"strips yellow pickled radish","raw":"4 strips yellow pickled radish","quantity":4,"ingredientId":"pickled-radish"},{"item":"Lebanese cucumber","raw":"1 Lebanese cucumber, cut into long batons","quantity":1,"ingredientId":"cucumber","prep":"cut into long batons"}]},{"title":"To roll","items":[{"item":"nori","raw":"4 nori sheets","quantity":4,"unit":"sheet","ingredientId":"nori"},{"item":"sesame oil","raw":"1 tsp sesame oil","quantity":1,"unit":"tsp","ingredientId":"sesame-oil"}]}],"steps":[{"text":"Rinse the rice until the water runs almost clear, then put it in a saucepan with the water and soak for 10 minutes. Bring to the boil, cover and cook on the lowest heat for 12 minutes, then rest covered for 10 minutes. Gently mix in the sesame oil, salt and sesame seeds and spread on a tray to cool until just warm."},{"text":"Heat a little oil in a frying pan over medium-low heat and cook the eggs as a thin omelette until set. Roll up and cut into long strips."},{"text":"Blanch the spinach in boiling water for 30 seconds, rinse under cold water and squeeze dry. Toss with the sesame oil and a pinch of salt. Stir-fry the carrot in a little oil for 2 minutes with a pinch of salt. Lightly fry the ham strips for 1 minute."},{"text":"Lay a nori sheet shiny side down on a bamboo mat. Spread a quarter of the rice thinly over it, leaving a 3cm strip bare at the far edge."},{"text":"Lay a quarter of each filling in neat lines across the middle of the rice. Using the mat, roll up firmly from the near side, pressing as you go, and seal the bare edge with a few grains of rice. Repeat with the rest."},{"text":"Brush the rolls with sesame oil. Slice into 1.5cm rounds with a sharp, wet knife."}],"notes":["Roll while the rice is still slightly warm, then eat within a few hours or refrigerate and eat the same day. For lunchboxes, keep cold with an ice brick.","Yellow pickled radish (danmuji) is sold in long strips at Asian grocers, sometimes in a gimbap pack with burdock."],"source":"user","provenance":"ai-draft"}},{"slug":"dakgalbi","title":"Dakgalbi","cuisine":"korean","meal_types":["dinner"],"diets":["no-dairy"],"difficulty":"easy","total_minutes":65,"recipe":{"id":"dakgalbi","title":"Dakgalbi","summary":"Spicy gochujang chicken stir-fried with cabbage, sweet potato and chewy rice cakes.","cuisine":"korean","diets":["no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":45,"cookMinutes":20,"servings":4,"onePot":true,"seasons":["autumn","winter"],"ingredientGroups":[{"title":"Marinade","items":[{"item":"gochujang","raw":"3 tbsp gochujang","quantity":3,"unit":"tbsp","ingredientId":"gochujang"},{"item":"gochugaru","raw":"1 tbsp gochugaru","quantity":1,"unit":"tbsp","ingredientId":"gochugaru"},{"item":"soy sauce","raw":"2 tbsp soy sauce","quantity":2,"unit":"tbsp","ingredientId":"soy-sauce"},{"item":"honey","raw":"1 tbsp honey","quantity":1,"unit":"tbsp","ingredientId":"honey"},{"item":"sesame oil","raw":"1 tbsp sesame oil","quantity":1,"unit":"tbsp","ingredientId":"sesame-oil"},{"item":"garlic","raw":"4 garlic cloves, finely grated","quantity":4,"unit":"clove","ingredientId":"garlic","prep":"finely grated"},{"item":"ginger","raw":"1 tsp ginger, finely grated","quantity":1,"unit":"tsp","ingredientId":"ginger","prep":"finely grated"}]},{"title":"Stir-fry","items":[{"item":"chicken thigh fillets","raw":"700g chicken thigh fillets, cut into bite-sized pieces","quantity":700,"unit":"g","ingredientId":"chicken-thigh","prep":"cut into bite-sized pieces"},{"item":"Korean rice cakes","raw":"200g Korean rice cakes (tteok)","quantity":200,"unit":"g","ingredientId":"rice-cakes","note":"tteok"},{"item":"neutral oil","raw":"1 tbsp neutral oil","quantity":1,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"cabbage","raw":"1/4 cabbage, cut into 4cm pieces","quantity":0.25,"ingredientId":"cabbage","prep":"cut into 4cm pieces"},{"item":"sweet potato","raw":"1 sweet potato, peeled, halved and cut into 5mm slices","quantity":1,"ingredientId":"sweet-potato","prep":"peeled, halved and cut into 5mm slices"},{"item":"brown onion","raw":"1 brown onion, sliced","quantity":1,"ingredientId":"brown-onion","prep":"sliced"},{"item":"spring onions","raw":"4 spring onions, cut into 4cm lengths","quantity":4,"ingredientId":"spring-onion","prep":"cut into 4cm lengths"},{"item":"sesame seeds","raw":"1 tsp sesame seeds","quantity":1,"unit":"tsp","ingredientId":"sesame-seeds"}]},{"title":"To serve","items":[{"item":"Steamed short-grain rice","raw":"Steamed short-grain rice","ingredientId":"sushi-rice"}]}],"steps":[{"text":"Mix the marinade, add the chicken and toss. Cover and refrigerate for 30 minutes, or up to a day."},{"text":"If the rice cakes are hard from the fridge, soak them in warm water for 10 minutes and drain."},{"text":"Heat the oil in a large, deep frying pan or wok over medium-high heat. Add the cabbage, sweet potato and onion and stir-fry for 3 minutes."},{"text":"Add the chicken with all its marinade, the rice cakes and 60ml water. Stir-fry for 10 to 12 minutes, until the sweet potato is tender, the rice cakes are soft and the chicken is cooked through (75°C in the thickest piece). Add a splash more water if it sticks."},{"text":"Toss through the spring onions for 1 minute, scatter with sesame seeds and serve with rice."}],"notes":["At home in Korea the leftovers are finished by frying rice in the pan with a little kimchi and sesame oil.","Gochujang and soy sauce contain wheat, so this isn't gluten-free.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"source":"user","provenance":"ai-draft"}},{"slug":"char-kway-teow","title":"Char Kway Teow","cuisine":"malaysian","meal_types":["dinner","lunch"],"diets":["pescatarian","no-dairy"],"difficulty":"medium","total_minutes":35,"recipe":{"id":"char-kway-teow","title":"Char Kway Teow","summary":"Smoky stir-fried flat rice noodles with prawns, egg, bean sprouts and garlic chives.","cuisine":"malaysian","diets":["pescatarian","no-dairy"],"mealTypes":["dinner","lunch"],"difficulty":"medium","prepMinutes":20,"cookMinutes":15,"servings":2,"onePot":false,"ingredientGroups":[{"title":"Sauce","items":[{"item":"dark soy sauce","raw":"2 tbsp dark soy sauce","quantity":2,"unit":"tbsp","ingredientId":"dark-soy-sauce"},{"item":"soy sauce","raw":"1 tbsp soy sauce","quantity":1,"unit":"tbsp","ingredientId":"soy-sauce"},{"item":"oyster sauce","raw":"1 tbsp oyster sauce","quantity":1,"unit":"tbsp","ingredientId":"oyster-sauce"},{"item":"sugar","raw":"1 tsp sugar","quantity":1,"unit":"tsp","ingredientId":"sugar"},{"item":"sambal oelek","raw":"2 tsp sambal oelek","quantity":2,"unit":"tsp","ingredientId":"sambal-oelek"}]},{"title":"Noodles","items":[{"item":"fresh flat rice noodles","raw":"500g fresh flat rice noodles","quantity":500,"unit":"g","ingredientId":"fresh-rice-noodles"},{"item":"neutral oil","raw":"3 tbsp neutral oil","quantity":3,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"garlic","raw":"4 garlic cloves, finely chopped","quantity":4,"unit":"clove","ingredientId":"garlic","prep":"finely chopped"},{"item":"raw prawns","raw":"250g raw prawns, peeled and deveined","quantity":250,"unit":"g","ingredientId":"prawn","prep":"peeled and deveined"},{"item":"fish cake","raw":"100g fish cake, thinly sliced","quantity":100,"unit":"g","ingredientId":"fish-cake","prep":"thinly sliced"},{"item":"eggs","raw":"2 eggs","quantity":2,"ingredientId":"egg"},{"item":"bean sprouts","raw":"150g bean sprouts","quantity":150,"unit":"g","ingredientId":"bean-sprouts"},{"item":"garlic chives","raw":"1 bunch garlic chives, cut into 4cm lengths","quantity":1,"unit":"bunch","ingredientId":"garlic-chives","prep":"cut into 4cm lengths"}]}],"steps":[{"text":"Mix the sauce ingredients. If the noodles are stiff from the fridge, pour hot water over them in a colander and gently separate them with your fingers. Drain well."},{"text":"Heat a wok over high heat until smoking. Add 2 tbsp oil and the garlic and stir for 10 seconds, then add the prawns and fish cake and stir-fry for 2 minutes, until the prawns are opaque."},{"text":"Add the noodles and the sauce and toss for 2 minutes, letting the noodles sit for a few seconds at a time so they char at the edges."},{"text":"Push the noodles to one side, add the rest of the oil and crack in the eggs. Scramble for 30 seconds, then toss everything together."},{"text":"Add the bean sprouts and chives and toss for 1 minute, until just wilted. Serve straight away."}],"notes":["Cook no more than two serves at a time. A crowded wok can't get hot enough for the smoky 'wok hei' flavour.","Hawkers add sliced Chinese sausage (lap cheong) and cockles. Add 1 sliced lap cheong with the prawns if you find it at an Asian grocer.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part. Cook mussels, clams and pipis only if they are alive and tightly closed (or close when tapped), and discard any that stay shut after cooking. Cook prawns until pink and opaque."],"source":"user","provenance":"ai-draft"}},{"slug":"sambal-udang","title":"Sambal Udang","cuisine":"malaysian","meal_types":["dinner"],"diets":["pescatarian","no-gluten","no-dairy"],"difficulty":"easy","total_minutes":55,"recipe":{"id":"sambal-udang","title":"Sambal Udang","summary":"Prawns cooked in a deep red, sweet, sour and fiery Malaysian chilli sambal.","cuisine":"malaysian","diets":["pescatarian","no-gluten","no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":30,"cookMinutes":25,"servings":4,"onePot":true,"ingredientGroups":[{"title":"Sambal paste","items":[{"item":"dried chillies","raw":"10 dried chillies, seeds shaken out","quantity":10,"ingredientId":"dried-chilli","prep":"seeds shaken out"},{"item":"long red chillies","raw":"3 long red chillies, chopped","quantity":3,"ingredientId":"red-chilli","prep":"chopped"},{"item":"shallots","raw":"6 shallots, chopped","quantity":6,"ingredientId":"shallot","prep":"chopped"},{"item":"garlic","raw":"4 garlic cloves","quantity":4,"unit":"clove","ingredientId":"garlic"},{"item":"shrimp paste","raw":"1 tsp shrimp paste","quantity":1,"unit":"tsp","ingredientId":"shrimp-paste"}]},{"title":"Prawns","items":[{"item":"neutral oil","raw":"4 tbsp neutral oil","quantity":4,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"red onion","raw":"1 red onion, cut into wedges","quantity":1,"ingredientId":"red-onion","prep":"cut into wedges"},{"item":"tamarind paste","raw":"2 tbsp tamarind paste","quantity":2,"unit":"tbsp","ingredientId":"tamarind-paste"},{"item":"palm sugar","raw":"2 tbsp palm sugar, grated","quantity":2,"unit":"tbsp","ingredientId":"palm-sugar","prep":"grated"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"},{"item":"raw prawns","raw":"800g raw prawns, peeled and deveined, tails on","quantity":800,"unit":"g","ingredientId":"prawn","prep":"peeled and deveined, tails on"}]},{"title":"To serve","items":[{"item":"Steamed jasmine rice","raw":"Steamed jasmine rice","ingredientId":"jasmine-rice"},{"item":"Lebanese cucumber","raw":"1 Lebanese cucumber, sliced","quantity":1,"ingredientId":"cucumber","prep":"sliced"}]}],"steps":[{"text":"Soak the dried chillies in just-boiled water for 20 minutes and drain. Blend with the fresh chillies, shallots, garlic, shrimp paste and 3 tbsp water to a smooth paste."},{"text":"Heat the oil in a wok or large frying pan over medium-low heat. Fry the paste for 12 to 15 minutes, stirring often, until it turns deep red, smells sweet rather than raw and the oil splits away."},{"text":"Add the onion and cook for 2 minutes. Stir in the tamarind, palm sugar, salt and 80ml water and simmer for 2 minutes. Taste: it should be hot, sweet and sour in balance."},{"text":"Add the prawns and cook, stirring, for 3 to 4 minutes, until they are pink and opaque all the way through. Serve with rice and cucumber."}],"notes":["Frying the paste slowly until the oil separates is the step that matters. Rushed sambal tastes raw and harsh.","Open a window when frying the paste; the chilli fumes are strong.","Food safety: Cook prawns and other crustaceans until the shells turn pink and the flesh is opaque and firm."],"source":"user","provenance":"ai-draft"}},{"slug":"soto-ayam","title":"Soto Ayam","cuisine":"indonesian","meal_types":["lunch","dinner"],"diets":["no-gluten","no-dairy"],"difficulty":"medium","total_minutes":75,"recipe":{"id":"soto-ayam","title":"Soto Ayam","summary":"Indonesian turmeric chicken soup with glass noodles, egg, bean sprouts and crisp shallots.","cuisine":"indonesian","diets":["no-gluten","no-dairy"],"mealTypes":["lunch","dinner"],"difficulty":"medium","prepMinutes":25,"cookMinutes":50,"servings":4,"onePot":false,"seasons":["autumn","winter"],"ingredientGroups":[{"title":"Spice paste","items":[{"item":"shallots","raw":"5 shallots, chopped","quantity":5,"ingredientId":"shallot","prep":"chopped"},{"item":"garlic","raw":"4 garlic cloves","quantity":4,"unit":"clove","ingredientId":"garlic"},{"item":"piece ginger","raw":"3cm piece ginger, chopped","quantity":3,"unit":"cm","ingredientId":"ginger","prep":"chopped"},{"item":"macadamias","raw":"4 macadamias","quantity":4,"ingredientId":"macadamias"},{"item":"ground turmeric","raw":"2 tsp ground turmeric","quantity":2,"unit":"tsp","ingredientId":"ground-turmeric"},{"item":"ground coriander","raw":"1 tsp ground coriander","quantity":1,"unit":"tsp","ingredientId":"ground-coriander"},{"item":"neutral oil","raw":"2 tbsp neutral oil","quantity":2,"unit":"tbsp","ingredientId":"neutral-oil"}]},{"title":"Soup","items":[{"item":"bone-in chicken thighs","raw":"1kg bone-in chicken thighs, skin removed","quantity":1,"unit":"kg","ingredientId":"chicken-thigh-bone-in","prep":"skin removed"},{"item":"water","raw":"2 litres water","quantity":2,"unit":"l","ingredientId":"water"},{"item":"lemongrass","raw":"2 lemongrass stalks, bruised and tied in a knot","quantity":2,"unit":"stalk","ingredientId":"lemongrass","prep":"bruised and tied in a knot"},{"item":"makrut lime","raw":"4 makrut lime leaves","quantity":4,"unit":"leaf","ingredientId":"makrut-lime-leaf"},{"item":"galangal","raw":"3 slices galangal","quantity":3,"unit":"slice","ingredientId":"galangal"},{"item":"salt","raw":"2 tsp salt","quantity":2,"unit":"tsp","ingredientId":"salt"}]},{"title":"To serve","items":[{"item":"glass noodles","raw":"100g glass noodles","quantity":100,"unit":"g","ingredientId":"glass-noodles"},{"item":"eggs","raw":"4 eggs","quantity":4,"ingredientId":"egg"},{"item":"bean sprouts","raw":"150g bean sprouts","quantity":150,"unit":"g","ingredientId":"bean-sprouts"},{"item":"wombok","raw":"1/4 wombok, finely shredded","quantity":0.25,"ingredientId":"wombok","prep":"finely shredded"},{"item":"fried shallots","raw":"3 tbsp fried shallots","quantity":3,"unit":"tbsp","ingredientId":"fried-shallots"},{"item":"limes","raw":"2 limes, cut into wedges","quantity":2,"ingredientId":"lime","prep":"cut into wedges"},{"item":"sambal oelek","raw":"2 tbsp sambal oelek","quantity":2,"unit":"tbsp","ingredientId":"sambal-oelek"}]}],"steps":[{"text":"Blend the shallots, garlic, ginger, macadamias, turmeric and coriander with 2 tbsp water to a paste. Heat the oil in a large pot over medium heat and fry the paste for 5 minutes, stirring, until fragrant."},{"text":"Add the chicken, water, lemongrass, lime leaves, galangal and salt. Bring to the boil, skim, then simmer gently, partly covered, for 35 minutes, until the chicken is very tender and cooked through (75°C at the bone)."},{"text":"Meanwhile, soak the glass noodles in hot water for 10 minutes and drain. Boil the eggs for 8 minutes, cool in cold water, peel and halve."},{"text":"Lift out the chicken, shred the meat and discard the bones. Remove the lemongrass, lime leaves and galangal. Return the chicken to the pot and season to taste."},{"text":"Divide the noodles, bean sprouts and wombok between deep bowls. Ladle over the hot soup and chicken. Top with egg and fried shallots, and serve with lime wedges and sambal."}],"notes":["Macadamias stand in for candlenuts (kemiri), which thicken the broth. Use 4 candlenuts if you find them at an Asian grocer.","Fried shallots are made in shared fryers, so check the packet if you need the dish gluten-free.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"source":"user","provenance":"ai-draft"}}]$q$::jsonb)), dn as (select r, row_number() over (partition by r->>'cuisine' order by r->>'slug') rn from d), cand as (select c.id, x.cuisine, row_number() over (partition by x.cuisine order by c.recipe_count, c.handle)-1 ix, count(*) over (partition by x.cuisine) cnt from public.cooks c join (select distinct cook_id, cuisine from public.published_recipes where status='published') x on x.cook_id=c.id where c.kind='person'), ins as (insert into public.published_recipes (cook_id,slug,title,cuisine,meal_types,diets,difficulty,total_minutes,recipe,review,status) select coalesce((select cd.id from cand cd where cd.cuisine=dn.r->>'cuisine' and cd.ix=(dn.rn-1)%cd.cnt),(select id from public.cooks where kind='official' limit 1)), dn.r->>'slug', dn.r->>'title', dn.r->>'cuisine', array(select jsonb_array_elements_text(dn.r->'meal_types')), array(select jsonb_array_elements_text(dn.r->'diets')), dn.r->>'difficulty', (dn.r->>'total_minutes')::int, jsonb_set(dn.r->'recipe','{notes}',coalesce((select jsonb_agg(n) from jsonb_array_elements(dn.r->'recipe'->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)), 'auto-checked','published' from dn where not exists (select 1 from public.published_recipes q where q.slug=dn.r->>'slug') on conflict do nothing returning id) select (select count(*) from d) expected, (select count(*) from ins) inserted;